import { spawnSync } from "child_process";
import { existsSync, readFileSync } from "fs";
import { join } from "path";

import test from "ava";

import {
  extractAnnotationsPerPage,
  extractFormFieldsPerPage,
  extractFormFieldsPerPageAsync,
  pdfDocument,
  pdfDocumentAsync,
  pdfMetadata,
  PdfDown
} from "../index";
import type { FormFieldType, PageFormField } from "../index";

// ── Fixtures (generated by `cargo run --example gen_fixtures`) ───────────────

const FIXTURES = join(import.meta.dirname, "fixtures", "forms");
const fixture = (name: string) => readFileSync(join(FIXTURES, name));

const basic = fixture("acroform-basic.pdf");
const inherited = fixture("acroform-inherited.pdf");
const cycle = fixture("acroform-cycle.pdf");
const orphans = fixture("acroform-orphans.pdf");
const many = fixture("acroform-many.pdf");
const rc4 = fixture("acroform-basic-rc4.pdf");
const aes256Path = join(FIXTURES, "acroform-basic-aes256.pdf");
const noForm = readFileSync(join(import.meta.dirname, "fixtures", "ascii85-dct-scan.pdf"));

const BASIC_NAMES = ["name", "notes", "zip", "agree", "color", "color", "color", "country", "tags", "sig", "submit"];

const byName = (fields: PageFormField[], name: string) => fields.filter((f) => f.name === name);
const one = <T extends FormFieldType>(fields: PageFormField[], name: string, type: T) => {
  const matches = byName(fields, name);
  if (matches.length !== 1) throw new Error(`expected one field named ${name}, got ${matches.length}`);
  const f = matches[0];
  if (f.type !== type) throw new Error(`expected ${name} to be ${type}, got ${f.type}`);
  return f as Extract<PageFormField, { type: T }>;
};

// ── Basic fixture ────────────────────────────────────────────────────────────

test("basic: 11 placements, 9 logical fields, reading order", (t) => {
  const fields = extractFormFieldsPerPage(basic);
  t.deepEqual(
    fields.map((f) => f.name),
    BASIC_NAMES
  );
  t.true(fields.every((f) => f.page === 1));
  t.true(fields.every((f) => f.rect.length === 4));
  const form = pdfMetadata(basic).form;
  t.is(form?.fieldCount, 9);
  t.is(form?.widgetCount, 11);
});

test("basic: text fields carry flags, limits and strings", (t) => {
  const fields = extractFormFieldsPerPage(basic);
  const name = one(fields, "name", "Text");
  t.is(name.value, "Jane Doe");
  t.is(name.tooltip, "Full name");
  t.is(name.mappingName, "fullName");
  t.false(name.multiline);
  const notes = one(fields, "notes", "Text");
  t.true(notes.multiline);
  t.is(notes.maxLen, 200);
  t.is(notes.value, "Line one\nLine two");
  const zip = one(fields, "zip", "Text");
  t.true(zip.comb);
  t.is(zip.maxLen, 5);
  t.is(zip.value, "60601");
});

test("basic: checkbox reports state name, export value and /AS state", (t) => {
  const agree = one(extractFormFieldsPerPage(basic), "agree", "Checkbox");
  t.is(agree.onState, "Ja");
  t.is(agree.exportValue, "Ja");
  t.true(agree.checked);
  t.true(agree.required);
  t.is(agree.value, "Ja");
});

test("basic: radio keeps /AP state names and /Opt export values apart", (t) => {
  const color = byName(extractFormFieldsPerPage(basic), "color");
  t.is(color.length, 3);
  t.is(new Set(color.map((f) => f.fieldObjectId)).size, 1);
  t.deepEqual(
    color.map((f) => f.widgetIndex),
    [0, 1, 2]
  );
  t.true(color.every((f) => f.widgetCount === 3));
  const radios = color.map((f) => {
    if (f.type !== "Radio") throw new Error(`expected Radio, got ${f.type}`);
    return f;
  });
  t.deepEqual(
    radios.map((f) => f.onState),
    ["0", "1", "2"]
  );
  t.deepEqual(
    radios.map((f) => f.exportValue),
    ["Red", "Green", "Blue"]
  );
  t.deepEqual(
    radios.map((f) => f.selected),
    [false, true, false]
  );
  t.true(radios.every((f) => f.value === "Green"));
});

test("basic: combo, list, push button, signature", (t) => {
  const fields = extractFormFieldsPerPage(basic);
  const country = one(fields, "country", "ComboBox");
  t.true(country.editable);
  t.deepEqual(country.options, [
    { exportValue: "US", displayValue: "United States" },
    { exportValue: "DE", displayValue: "Germany" }
  ]);
  t.is(country.value, "US");
  const tags = one(fields, "tags", "ListBox");
  t.true(tags.multiSelect);
  t.deepEqual(tags.values, ["a", "c"]);
  t.is(tags.value, "a");
  const submit = one(fields, "submit", "PushButton");
  t.true(submit.hasActions);
  const sig = one(fields, "sig", "Signature");
  t.false(sig.signed);
  t.is(sig.value, undefined);
});

// ── Inherited fixture ────────────────────────────────────────────────────────

test("inherited: dotted names, inherited flags, UTF-16, PDFDocEncoding, indirect /V", (t) => {
  const fields = extractFormFieldsPerPage(inherited);
  const first = one(fields, "person.first", "Text");
  const last = one(fields, "person.last", "Text");
  t.true(first.readOnly);
  t.true(last.readOnly);
  t.is(first.value, "Ada");
  t.is(last.value, "Müller");
  t.is(first.partialName, "first");
  t.is(one(fields, "Straße", "Text").value, "x");
  t.is(one(fields, "amount", "Text").value, "42");
  t.is(one(fields, "badrect", "Text").rect.length, 3);
  t.is(one(fields, "indirect", "Text").value, "via ref");
});

test("inherited: multi-page placement, duplicate names, reading order", (t) => {
  const fields = extractFormFieldsPerPage(inherited);
  t.is(fields.length, 10);
  const id = byName(fields, "id");
  t.deepEqual(
    id.map((f) => f.page),
    [2, 3]
  );
  t.deepEqual(
    id.map((f) => f.widgetIndex),
    [0, 1]
  );
  t.true(id.every((f) => f.widgetCount === 2 && f.value === "A-1"));
  t.is(id[0].fieldObjectId, id[1].fieldObjectId);
  const dup = byName(fields, "dup");
  t.is(dup.length, 2);
  t.not(dup[0].fieldObjectId, dup[1].fieldObjectId);
  t.deepEqual(
    dup.map((f) => f.value),
    ["one", "two"]
  );
  t.deepEqual(
    fields.map((f) => `${f.page}:${f.name}`),
    [
      "1:person.first",
      "1:person.last",
      "1:dup",
      "1:dup",
      "1:Straße",
      "1:amount",
      "1:indirect",
      "1:badrect",
      "2:id",
      "3:id"
    ]
  );
});

test("inherited: unplaced fields keep their payload, the inline kid keeps the field's own id", (t) => {
  const form = pdfMetadata(inherited).form;
  t.truthy(form);
  t.is(form?.fieldCount, 12);
  t.is(form?.widgetCount, 10);
  t.deepEqual(
    form?.unplacedFields.map((u) => u.name),
    ["hidden", "inlinekid", "sealed"]
  );
  const hidden = form?.unplacedFields[0];
  t.is(hidden?.type, "Text");
  t.is(hidden?.value, "secret");
  const inlinekid = form?.unplacedFields[1];
  t.regex(inlinekid?.fieldObjectId ?? "", /^\d+ \d+ obj$/);
  t.false(/\/kid/.test(inlinekid?.fieldObjectId ?? ""));
  const sealed = form?.unplacedFields[2];
  t.is(sealed?.type, "Signature");
  t.true(sealed?.signed);
  t.is(sealed?.value, undefined);
});

// ── Real-world invoices (shared with the OCR package fixtures) ───────────────

const INVOICES = join(import.meta.dirname, "..", "ocr", "__test__", "fixtures");

test("real world: WHMCS invoice carries an empty /AcroForm", (t) => {
  const buf = readFileSync(join(INVOICES, "Downloadable-PDF-Invoices-Add-On-Samples.pdf"));
  const form = pdfMetadata(buf).form;
  t.true(form?.hasAcroForm);
  t.is(form?.fieldCount, 0);
  t.is(form?.widgetCount, 0);
  t.deepEqual(form?.unplacedFields, []);
  t.deepEqual(extractFormFieldsPerPage(buf), []);
  const doc = pdfDocument(buf);
  t.deepEqual(doc.formFields, []);
  t.deepEqual(doc.formFieldPages, []);
  t.is(doc.totalFormFields, 0);
  t.true(doc.form?.hasAcroForm);
});

test("real world: Sliced Invoices sample has no form at all", (t) => {
  const buf = readFileSync(join(INVOICES, "wordpress-pdf-invoice-plugin-sample.pdf"));
  t.is(pdfMetadata(buf).form, undefined);
  t.deepEqual(extractFormFieldsPerPage(buf), []);
});

// ── Cycle, orphans, no form, scale ───────────────────────────────────────────

test("cycle: terminates with the single placed field", (t) => {
  const fields = extractFormFieldsPerPage(cycle);
  t.is(fields.length, 1);
  t.is(fields[0].name, "A.B");
  t.is(pdfMetadata(cycle).form?.fieldCount, 1);
});

test("orphans: widgets without /AcroForm are Unknown; annotations keep them", (t) => {
  const fields = extractFormFieldsPerPage(orphans);
  t.deepEqual(
    fields.map((f) => f.name),
    ["ghost", "inline"]
  );
  t.true(fields.every((f) => f.type === "Unknown"));
  t.is(fields[0].value, "boo");
  t.is(fields[1].objectId, "page 2 annot 0");
  t.is(fields[1].page, 2);
  const form = pdfMetadata(orphans).form;
  t.false(form?.hasAcroForm);
  t.is(form?.fieldCount, 0);
  t.is(form?.widgetCount, 2);
  t.is(extractAnnotationsPerPage(orphans).filter((a) => a.subtype === "Widget").length, 2);
});

test("no form: existing fixture yields an empty array and no form info", (t) => {
  t.deepEqual(extractFormFieldsPerPage(noForm), []);
  t.is(pdfMetadata(noForm).form, undefined);
});

test("many: 1,500 placements on 30 pages in page order", (t) => {
  const started = performance.now();
  const fields = extractFormFieldsPerPage(many);
  const elapsed = performance.now() - started;
  t.is(fields.length, 1500);
  t.is(fields[0].page, 1);
  t.is(fields[fields.length - 1].page, 30);
  for (let i = 1; i < fields.length; i++) {
    t.true(fields[i].page >= fields[i - 1].page, `page order broke at index ${i}`);
  }
  t.deepEqual(pdfMetadata(many).form?.fieldCount, 1500);
  t.log(`1,500 placements extracted in ${elapsed.toFixed(1)} ms (measurement, not an assertion)`);
});

// ── Encryption with an empty user password ───────────────────────────────────

test("encrypted RC4-128, empty user password: same fields as plaintext", (t) => {
  const fields = extractFormFieldsPerPage(rc4);
  t.deepEqual(
    fields.map((f) => f.name),
    BASIC_NAMES
  );
  t.is(one(fields, "name", "Text").value, "Jane Doe");
  t.is(one(fields, "notes", "Text").value, "Line one\nLine two");
});

(existsSync(aes256Path) ? test : test.skip)("encrypted AES-256, empty user password: same fields as plaintext", (t) => {
  const fields = extractFormFieldsPerPage(readFileSync(aes256Path));
  t.deepEqual(
    fields.map((f) => f.name),
    BASIC_NAMES
  );
  t.is(one(fields, "name", "Text").value, "Jane Doe");
});

// ── API parity ───────────────────────────────────────────────────────────────

test("sync, async and class agree", async (t) => {
  for (const buf of [basic, inherited]) {
    const sync = extractFormFieldsPerPage(buf);
    t.deepEqual(await extractFormFieldsPerPageAsync(buf), sync);
    const pdf = new PdfDown(buf);
    t.deepEqual(pdf.formFieldsPerPage(), sync);
    t.deepEqual(await pdf.formFieldsPerPageAsync(), sync);
  }
});

// ── Aggregates ───────────────────────────────────────────────────────────────

test("pdfMetadata: form info present on forms, absent otherwise", (t) => {
  const form = pdfMetadata(basic).form;
  t.true(form?.hasAcroForm);
  t.true(form?.needAppearances);
  t.false(form?.hasXfa);
  t.is(form?.sigFlags, 0);
  t.deepEqual(form?.unplacedFields, []);
  t.false(form?.truncated);
  t.deepEqual(form?.warnings, []);
  t.is(pdfMetadata(noForm).form, undefined);
});

test("pdfDocument: aggregates mirror images and annotations", (t) => {
  const doc = pdfDocument(inherited);
  t.is(doc.totalFormFields, doc.formFields.length);
  t.is(doc.totalFormFields, 10);
  t.deepEqual(doc.formFieldPages, [1, 2, 3]);
  t.deepEqual(doc.form, pdfMetadata(inherited).form);
  t.deepEqual(doc.formFields, extractFormFieldsPerPage(inherited));
  const plain = pdfDocument(noForm);
  t.deepEqual(plain.formFields, []);
  t.is(plain.totalFormFields, 0);
  t.deepEqual(plain.formFieldPages, []);
  t.is(plain.form, undefined);
});

test("pdfDocumentAsync and PdfDown.document agree on form data", async (t) => {
  const sync = pdfDocument(basic);
  const async_ = await pdfDocumentAsync(basic);
  const pdf = new PdfDown(basic);
  for (const other of [async_, pdf.document(), await pdf.documentAsync()]) {
    t.deepEqual(other.form, sync.form);
    t.deepEqual(other.formFields, sync.formFields);
    t.deepEqual(other.formFieldPages, sync.formFieldPages);
    t.is(other.totalFormFields, sync.totalFormFields);
  }
});

// ── Cross-check against qpdf when it is installed ────────────────────────────

const hasQpdf = spawnSync("qpdf", ["--version"]).status === 0;

interface QpdfAcroForm {
  hasacroform: boolean;
  needappearances: boolean;
  fields: Array<{ fullname: string; pageposfrom1: number }>;
}

(hasQpdf ? test : test.skip)("qpdf agrees on placed field names, pages and form flags", (t) => {
  for (const name of ["acroform-basic.pdf", "acroform-inherited.pdf"]) {
    const ours = extractFormFieldsPerPage(fixture(name));
    const raw = spawnSync("qpdf", ["--json", "--json-key=acroform", join(FIXTURES, name)], { encoding: "utf8" });
    const theirs = (JSON.parse(raw.stdout) as { acroform: QpdfAcroForm }).acroform;
    const placed = theirs.fields.filter((f) => f.pageposfrom1);
    t.deepEqual(
      ours.map((f) => `${f.page}:${f.name}`).sort(),
      placed.map((f) => `${f.pageposfrom1}:${f.fullname}`).sort()
    );
    const form = pdfMetadata(fixture(name)).form;
    t.is(form?.hasAcroForm, theirs.hasacroform);
    t.is(form?.needAppearances, theirs.needappearances);
  }
});
